update public.listings set details = details ||
  '{"brand":"Audi","model":"A4","gearbox":"automaat","power":110,"color":"hall"}'::jsonb where id=1;
create temp table kw_rows_before as select
 (select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,'')) from public.listings x) listings,
 (select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,'')) from public.listing_images x) images,
 (select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,'')) from public.identities x) identities,
 (select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,'')) from public.identity_profiles x) profiles,
 (select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,'')) from public.user_blocks x) blocks;

select pg_temp.kw_assert((select not prosecdef and provolatile='i' and proparallel='s' and proconfig=array['search_path=pg_catalog, pg_temp'] from pg_proc where oid='public.public_listing_search_document_v1(text,text,text,text,jsonb)'::regprocedure), 'pure immutable invoker helper');
select pg_temp.kw_assert((select prosecdef and provolatile='s' and proconfig @> array['search_path=pg_catalog, public, auth, pg_temp','plan_cache_mode=force_custom_plan'] from pg_proc where oid='public.search_public_listings_v1(text,text,text,text,text,text,integer,integer)'::regprocedure), 'search keeps stable definer and query-local planning');
select pg_temp.kw_assert((select a.amname='gin' and i.indisvalid and i.indisready and pg_get_indexdef(i.indexrelid) like '%public_listing_search_document_v1%' and pg_get_expr(i.indpred,i.indrelid) like '%active%' from pg_index i join pg_class c on c.oid=i.indexrelid join pg_am a on a.oid=c.relam where i.indexrelid='public.listings_public_keywords_v1_gin'::regclass), 'matching active-only GIN index valid');
select pg_temp.kw_assert(not exists(select 1 from pg_proc p, lateral aclexplode(p.proacl) a where p.oid='public.public_listing_search_document_v1(text,text,text,text,jsonb)'::regprocedure and a.grantee=0), 'no PUBLIC grant public.public_listing_search_document_v1');
select pg_temp.kw_assert(has_function_privilege('anon','public.public_listing_search_document_v1(text,text,text,text,jsonb)','execute'), 'anon execute public.public_listing_search_document_v1');
select pg_temp.kw_assert(has_function_privilege('authenticated','public.public_listing_search_document_v1(text,text,text,text,jsonb)','execute'), 'authenticated execute public.public_listing_search_document_v1');
select pg_temp.kw_assert(has_function_privilege('service_role','public.public_listing_search_document_v1(text,text,text,text,jsonb)','execute'), 'service_role execute public.public_listing_search_document_v1');
select pg_temp.kw_assert(not exists(select 1 from pg_proc p, lateral aclexplode(p.proacl) a where p.oid='public.search_public_listings_v1(text,text,text,text,text,text,integer,integer)'::regprocedure and a.grantee=0), 'no PUBLIC grant public.search_public_listings_v1');
select pg_temp.kw_assert(has_function_privilege('anon','public.search_public_listings_v1(text,text,text,text,text,text,integer,integer)','execute'), 'anon execute public.search_public_listings_v1');
select pg_temp.kw_assert(has_function_privilege('authenticated','public.search_public_listings_v1(text,text,text,text,text,text,integer,integer)','execute'), 'authenticated execute public.search_public_listings_v1');
select pg_temp.kw_assert(has_function_privilege('service_role','public.search_public_listings_v1(text,text,text,text,text,text,integer,integer)','execute'), 'service_role execute public.search_public_listings_v1');
set local role anon;
select pg_temp.kw_assert(public.search_public_listings_v1()->>'total_count'='83', 'public eligibility total preserved');
select pg_temp.kw_assert(jsonb_array_length(public.search_public_listings_v1()->'items')=24, 'default page bounded');
select pg_temp.kw_assert(public.search_public_listings_v1()#>>'{items,0,content_id}'='90' and public.search_public_listings_v1()#>>'{items,1,content_id}'='89', 'newest deterministic tie unchanged');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'Audi A4 automaat')->>'total_count'='1' and public.search_public_listings_v1(p_search_query=>'Audi A4 automaat')#>>'{items,0,content_id}'='1', 'brand model gearbox across title and details');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'audi A4 sõiduauto 110')->>'total_count'='1', 'description text numeric value and details intersect');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'A4 hall')->>'total_count'='1', 'detail-only values searchable without duplicate description');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'Audi automatic')->>'total_count'='0', 'no invented language synonyms');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'aud A4')->>'total_count'='0', 'no implicit prefix');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'Audi A4 puuduv')->>'total_count'='0', 'AND semantics retained');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'Audi',p_category=>'vehicles',p_subcategory=>'cars',p_detail_category=>'passenger_cars')->>'total_count'='1', 'category filter and new keywords intersect');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'Audi',p_condition=>'damaged')->>'total_count'='0', 'condition still filters before count');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'Audi',p_location_query=>'Paide')->>'total_count'='1', 'public city still filters before count');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'Audi',p_result_offset=>1)->>'total_count'='1' and public.search_public_listings_v1(p_search_query=>'Audi',p_result_offset=>1)->'items'='[]'::jsonb, 'offset does not change keyword total');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'automatic',p_result_limit=>10)->>'next_offset'='10', 'keyword pagination metadata');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>null)->>'total_count'='83', 'null query remains browse');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'!!!')->>'total_count'='0', 'punctuation does not broaden');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'Audi')#>>'{items,0,price}'='2500 USD' and public.search_public_listings_v1(p_search_query=>'Audi')#>'{items,0,currency}'='null'::jsonb, 'money no fabricated currency');
