select pg_temp.kw_assert(not (public.public_listing_search_document_v1('','','vehicles','cars','{"detailCategory": "passenger_cars", "vehicleBrand": "hiddenkeytoken"}'::jsonb) @@ plainto_tsquery('pg_catalog.simple','hiddenkeytoken')), 'excluded key vehicleBrand');
