select pg_temp.kw_assert(not (public.public_listing_search_document_v1('','','vehicles','cars','{"brand":["hiddenkeytoken"],"model":{"value":"hiddenkeytoken"},"gearbox":true,"detailCategory":"passenger_cars"}'::jsonb) @@ plainto_tsquery('pg_catalog.simple','hiddenkeytoken')), 'shape guard nested or boolean detail values');
