select pg_temp.kw_assert(public.public_listing_search_document_v1('','','electronics','phones','{"brand":"Nokia","model":3310}'::jsonb) @@ plainto_tsquery('pg_catalog.simple','Nokia 3310'), 'valid two-level path does not require detail selector');
select pg_temp.kw_assert(not (public.public_listing_search_document_v1(repeat(' ',4096)||'beyondtitle','',null,null,null) @@ plainto_tsquery('pg_catalog.simple','beyondtitle')), 'title index window bounded without source mutation');
select pg_temp.kw_assert(not (public.public_listing_search_document_v1('',repeat(' ',32768)||'beyondbody',null,null,null) @@ plainto_tsquery('pg_catalog.simple','beyondbody')), 'description index window bounded without source mutation');
select pg_temp.kw_assert(not (public.public_listing_search_document_v1('','','electronics','phones',jsonb_build_object('brand',repeat(' ',1024)||'beyonddetail')) @@ plainto_tsquery('pg_catalog.simple','beyonddetail')), 'detail value index window bounded');
savepoint index_plan; set local enable_seqscan=off; set local jit=off;
do $plan$ declare plan json; begin
  execute $query$explain (format json) select id from public.listings
    where status='active' and public.public_listing_search_document_v1(title,description,category,subcategory,details)
      @@ plainto_tsquery('pg_catalog.simple','Audi A4')$query$ into plan;
  perform pg_temp.kw_assert(plan::text like '%listings_public_keywords_v1_gin%', 'GIN expression is planner-usable');
end; $plan$;
rollback to savepoint index_plan;
select set_config('request.jwt.claim.sub','44444444-4444-4444-8444-000000000001',true); set local role authenticated;
select pg_temp.kw_assert(public.search_public_listings_v1()->>'total_count'='81', 'authenticated blocks precede count');
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'automatic')->>'total_count'='76', 'details matches obey both block directions');
select pg_temp.kw_assert(not exists(select 1 from jsonb_array_elements(public.search_public_listings_v1(p_search_query=>'automatic',p_result_limit=>60,p_result_offset=>30)->'items') x where x->>'content_id' in ('14','15')), 'blocked details absent after pagination');
reset role; select set_config('request.jwt.claim.sub','',true); set local role service_role;
select pg_temp.kw_assert(public.search_public_listings_v1()->>'total_count'='83', 'service role still sees public eligibility only');
reset role;
savepoint local_settings; set local plan_cache_mode=force_generic_plan;
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'Audi')->>'total_count'='1' and current_setting('plan_cache_mode')='force_generic_plan', 'custom planning setting restored to caller');
rollback to savepoint local_settings;
savepoint write_cases;
grant select, insert, update, delete on table public.listings to authenticated;
create policy kw_fixture_writer on public.listings for all to authenticated
  using (user_id=auth.uid()) with check (user_id=auth.uid());
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-000000000001',true);
set local role authenticated;
insert into public.listings(id,user_id,identity_id,title,description,category,subcategory,details,status)
values(901,'22222222-2222-4222-8222-000000000001','11111111-1111-4111-8111-000000000001',
 'indexed row','', 'vehicles','cars','{"detailCategory":"passenger_cars","gearbox":"newindextoken"}','active');

select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'newindextoken')->>'total_count'='1', 'ordinary fixture writer can maintain expression index');
update public.listings set category='clothing_fashion',subcategory='men', details=details - 'detailCategory' where id=901;
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'newindextoken')->>'total_count'='0', 'category change removes stale unrelated field from index');
update public.listings set details='{"material":"linanetoken","size":"XL"}' where id=901;
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'linanetoken XL')->>'total_count'='1', 'clothing public material and size searchable');
update public.listings set status='paused' where id=901;
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'linanetoken')->>'total_count'='0', 'status update removes partial-index candidate');
update public.listings set status='active',category='electronics',subcategory='computers',details='{"brand":"delltoken","processor":"ryzentoken","ram":"16 GB"}' where id=901;
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'delltoken ryzentoken 16')->>'total_count'='1', 'electronics structured text values searchable');
update public.listings set category='home_garden',subcategory='furniture',details='{"material":"tammetoken","color":"valgetoken"}' where id=901;
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'tammetoken valgetoken')->>'total_count'='1', 'furniture structured text values searchable');
update public.listings set category='real_estate',subcategory='apartments',details='{"rooms":"3","heating_type":"maakuttetoken","district":"privateroadtoken"}' where id=901;
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'3 maakuttetoken')->>'total_count'='1' and public.search_public_listings_v1(p_search_query=>'privateroadtoken')->>'total_count'='0', 'property scalar values without excluded locality field');
delete from public.listings where id=901;
select pg_temp.kw_assert(public.search_public_listings_v1(p_search_query=>'maakuttetoken')->>'total_count'='0', 'test deletion updates index visibility');
reset role; rollback to savepoint write_cases;
select pg_temp.kw_assert((select listings=(select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,'')) from public.listings x)
 and images=(select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,'')) from public.listing_images x)
 and identities=(select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,'')) from public.identities x)
 and profiles=(select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,'')) from public.identity_profiles x)
 and blocks=(select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,'')) from public.user_blocks x)
 from kw_rows_before), 'all fixture source rows preserved');
select 'PUBLIC_LISTING_DETAIL_KEYWORDS_SUITE=PASS';
rollback;
